# Generated by build.py from recipe.yml for recipe surl-run-a-fixture-from-pester. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/greeting.txt'), "Welcome aboard.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'expected-greeting.txt'), "Welcome aboard.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'Server.Tests.ps1'), "# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Pester tests against a surl that BeforeAll starts on a free port and AfterAll stops, which`n# Pester runs even when a test fails. The checks throw, so the file runs on Pester 5 and 3.4.`nDescribe 'the site served by surl' {`n    BeforeAll {`n        # Start surl on port 0 and read its first line, Listening on <url>, for the port it bound.`n        Remove-Item surl.log -ErrorAction Ignore`n        `$start = [Diagnostics.ProcessStartInfo]::new((Get-Command surl -CommandType Application)[0].Source)`n        foreach (`$argument in '-v', '--log-file', 'surl.log', '--directory', 'site', 'http://127.0.0.1:0/') {`n            `$start.ArgumentList.Add(`$argument)`n        }`n        `$start.RedirectStandardOutput = `$true`n        `$surl = [Diagnostics.Process]::Start(`$start)`n        `$surl.Id | Set-Content surl.pid`n        `$line = `$surl.StandardOutput.ReadLine()`n        if (`$line -notmatch '^Listening on (http://\S+)`$') {`n            `$surl.WaitForExit()`n            throw `"surl did not start: exit `$(`$surl.ExitCode)`"`n        }`n        `$url = `$Matches[1]`n    }`n`n    AfterAll {`n        # Stop surl however the tests went, and wait until it has gone.`n        if (`$surl -and -not `$surl.HasExited) {`n            `$surl.Kill()`n            `$surl.WaitForExit()`n        }`n    }`n`n    It 'listens on a port the system chose' {`n        if (`$url -notmatch '^http://127\.0\.0\.1:[1-9][0-9]*/`$') { throw `"unexpected URL `$url`" }`n    }`n`n    It 'serves the greeting' {`n        `$body = curl -fsS `"`${url}greeting.txt`"`n        `$expected = Get-Content expected-greeting.txt`n        if (`$body -ne `$expected) { throw `"expected '`$expected', got '`$body'`" }`n    }`n`n    It 'answers 404 for a missing file' {`n        `$status = curl -s -o missing.out -w '%{http_code}' `"`${url}missing.txt`"`n        if (`$status -ne '404') { throw `"expected 404, got `$status`" }`n    }`n}`n")
[IO.File]::WriteAllText((Join-Path $PWD 'run-tests.ps1'), "# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Runs the Pester tests and exits with the number that failed, so a CI step fails with them.`n`$result = Invoke-Pester -Path ./Server.Tests.ps1 -PassThru`n`"passed `$(`$result.PassedCount), failed `$(`$result.FailedCount)`"`nexit `$result.FailedCount`n")
pwsh -NoProfile -File run-tests.ps1
